   192	/// terminal screen, so it is likely a subset of the window size. The dimensions
   193	/// should be in pixels.
   194	pub const ScreenSize = extern struct {
   195	    width: u32,
   196	    height: u32,
   197	
   198	    /// Subtract padding from the screen size.
   199	    pub fn subPadding(self: ScreenSize, padding: Padding) ScreenSize {
   200	        return .{
   201	            .width = self.width -| (padding.left + padding.right),
   202	            .height = self.height -| (padding.top + padding.bottom),
   203	        };
   204	    }
   205	
   206	    /// Calculates the amount of blank space around the grid. This is possible
   207	    /// when padding isn't balanced.
   208	    ///
   209	    /// The "self" screen size here should be the unpadded screen.
   210	    pub fn blankPadding(self: ScreenSize, padding: Padding, grid: GridSize, cell: CellSize) Padding {
   211	        const grid_width = grid.columns * cell.width;
   212	        const grid_height = grid.rows * cell.height;
   213	        const padded_width = grid_width + (padding.left + padding.right);
   214	        const padded_height = grid_height + (padding.top + padding.bottom);
   215	
   216	        // Note these have to use a saturating subtraction to avoid underflow
   217	        // because our padding can cause the padded sizes to be larger than
   218	        // our real screen if the screen is shrunk to a minimal size such
   219	        // as 1x1.
   220	        const leftover_width = self.width -| padded_width;
   221	        const leftover_height = self.height -| padded_height;
   222	
   223	        return .{
   224	            .top = 0,
   225	            .bottom = leftover_height,
   226	            .right = leftover_width,
   227	            .left = 0,
   228	        };
   229	    }
   230	
   231	    /// Returns true if two sizes are equal.
   232	    pub fn equals(self: ScreenSize, other: ScreenSize) bool {
   233	        return self.width == other.width and self.height == other.height;
   234	    }
   235	};
